-- Second German article translations batch (deepening phase, after the
-- first full cycle through all six languages). Three more articles:
-- Things to do in Maldives, Most Famous Places In The World, and the
-- Maldives Honeymoon guide. Same conventions: canonical English entity_id
-- kept, own German slug/title/body, internal links inside the body still
-- point at the English URLs (those verticals aren't translated yet).
insert into translations (entity_id, entity_type, locale, slug, title, short_description, description, body_html, meta_title, meta_description, translation_status, translated_by) values
  ((select id from nodes where node_type = 'article' and slug = 'things-to-do-in-maldives'), 'article', 'de', 'dinge-die-man-auf-den-maldiven-tun-kann', 'Dinge, die man auf den Maldiven tun kann', 'Die Top 12 Aktivitäten auf den Maldiven für Ihren Urlaub. Die meisten dieser Aktivitäten sind in allen Resorts verfügbar.', null, '<h3>Schnorcheln</h3><p>Die Malediven bieten einige der spektakulärsten Schnorchelmöglichkeiten der Welt. Dies liegt an der Fülle von Korallenriffen in der Region sowie an dem extrem klaren Wasser. Tatsächlich gibt es fast 70 verschiedene Korallenriffarten und mehr als 700 Arten von Meereslebewesen. Das bedeutet, wenn Sie hier schnorcheln, werden Sie garantiert eine erstaunliche Vielfalt an Flora und Fauna sehen. Zu den Arten, die Sie wahrscheinlich sehen werden, gehören Riffhaie, verschiedene Schildkrötenarten, Rochen, Napoleon-Fische und Muränen. Egal, ob Sie ein Experte für Meereslebewesen sind oder nicht, Sie werden die farbenfrohe Vielfalt der Lebewesen zu schätzen wissen, die Sie beobachten können. Schnorcheln ist eine sehr empfehlenswerte Aktivität auf den Malediven.</p><figure><img src="legacy/images/articles/snorkeling.webp" alt="maldives" loading="lazy" /></figure><h3>Tauchen</h3><p>Die Malediven sind aufgrund der weißen Sandstrände, Korallenriffe, klaren warmen Gewässer, zahlreichen Tauchplätze und der reichen Meeresfauna zu einem der besten Tauchziele der Welt geworden.</p><p>Die meisten Ferienresorts auf den Malediven verfügen über eine Tauchstation, und es gibt eine Reihe von Liveaboard-Anbietern, die Tauchkreuzfahrten anbieten, die Gäste zu vielen Tauchplätzen auf den gesamten Malediven bringen. Viele Taucher möchten auf den Malediven tauchen, weil hier Walhaie, Mantarochen, Adlerrochen, Riffhaie, Hammerhaie und Muränen sowie viele kleinere Fisch- und Korallenarten vorkommen. Tauchen ist eine der besten Aktivitäten auf den Malediven.</p><figure><img src="legacy/images/articles/maldives-diving.webp" alt="maldives" loading="lazy" /></figure><h3>Angeln</h3><p>Die Malediven sind als eines der besten Großwildangel-Ziele der Welt bekannt und beheimaten eine Fülle an pelagischen Fischen wie Thunfisch, Goldmakrele, Wahoo, Barracuda und Schwertfisch. Die Malediven haben strenge Angelvorschriften, die weitgehend durchgesetzt werden, um die Fischbestände für den Lebensunterhalt der einheimischen Bevölkerung zu erhalten.</p><figure><img src="legacy/images/articles/fishing.webp" alt="maldives" loading="lazy" /></figure><h3>Strände</h3><p>Die Strände der Malediven sind berühmt für ihre Weiße und ihr kristallklares Wasser. An manchen Orten der Malediven können die Strände nachts leuchten, was durch marine Planktonarten verursacht wird. Der Strand von <a href="/maldives/islands/fuvahmulah/">Fuvahmulah</a> ist berühmt für seine leuchtenden Steine.</p><figure><img src="legacy/images/articles/maldives-sand-bank.webp" alt="maldives" loading="lazy" /></figure><h3>Yoga</h3><p>Yoga ist eine Gruppe von körperlichen, geistigen und spirituellen Praktiken oder Disziplinen, die im alten Indien entstanden sind. Yoga ist eine der sechs orthodoxen Schulen der hinduistischen philosophischen Traditionen. In den Resorts der Malediven wird eine breite Palette an Yoga-Sitzungen angeboten, die beste Zeit für Yoga ist bei Sonnenaufgang und Sonnenuntergang.</p><h3>Spa</h3><p>Viele Arten von Körpermassagen werden von fast allen Resorts auf den Malediven angeboten. Auch viele international bekannte Spa-Marken sind auf den Malediven vertreten.</p><h3>Unterwasser-Dining</h3><p>Die Malediven haben das erste Unterwasserrestaurant der Welt. Insgesamt sind 6 Unterwasserrestaurants in verschiedenen Gebieten verfügbar. Diese mehrere Meter unter dem Meeresspiegel gebauten Restaurants bieten durch Glasdecken atemberaubende Ausblicke auf das Meeresleben und definieren das Erlebnis des Unterwasser-Dinings auf den Malediven völlig neu.</p><h3>Inselhüpfen</h3><p>Inselhüpfen ist die beste Möglichkeit, die lokale Kultur und Geschichte der Malediven zu entdecken. Es gibt 200 lokale Inseln auf den Malediven, und fast alle Resorts und Hotels bieten Touristen Ausflüge zu diesen lokalen Inseln an.</p><p>Die Stadt Malé ist die Hauptstadt der Malediven und ein großartiger Ort mit vielen wichtigen und interessanten Sehenswürdigkeiten. Wenn Sie in einem Resort wohnen, ist der beste Weg, die Hauptstadt zu besuchen, an Ihrem Abreisetag: Kommen Sie früher am Flughafen Malé International an und nehmen Sie die 10-minütige Fahrt vom Flughafen. Dies ist eine der besten Aktivitäten, wenn Sie Wartezeit am Flughafen Malé haben.</p><figure><img src="legacy/images/articles/day-tours-to-villages.webp" alt="maldives" loading="lazy" /></figure><h3>Wal-U-Boot</h3><p>Das Wal-U-Boot ist die beste Option für Nichtschwimmer und Nichttaucher. Das Meeresleben der Malediven ist der reichste Schatz des Landes. Wenn Sie aus irgendeinem Grund nicht tauchen oder unter Wasser gehen können, keine Sorge – die Malediven bieten Wal-U-Boot-Ausflüge an.</p><h3>Surfen</h3><p>Das Surfen auf den Malediven wird durch den Nordost- und den Südwestmonsun beeinflusst. Während des Nordostmonsuns (von März bis April) sind die Bedingungen in den südlichen Atollen optimal. Von Mai bis Oktober, während des Südwestmonsuns, ist das beste Surfgebiet in den nördlichen oder zentralen Atollen.</p><h3>Einkaufen auf den Malediven</h3><p>Souvenir-Shopping ist auf den Malediven bei Besuchern sehr beliebt. Souvenirläden bieten lokal hergestellte Artikel, Korallen, Muscheln und viele handgefertigte Gegenstände an. Die Stadt Malé ist der bemerkenswerteste Ort für Souvenir-Einkäufe, Online-Shopping und Lieferung sind ebenfalls verfügbar.</p><figure><img src="legacy/images/articles/maldives-shopping.webp" alt="maldives" loading="lazy" /></figure><h3>Ausflüge &amp; Wassersport</h3><p>Es gibt viele weitere Arten von Ausflügen und Wassersportarten auf den Malediven. Unten finden Sie eine Liste der gängigsten Ausflüge.</p><p>Mantarochen-Beobachtung Walbeobachtung Delfinbeobachtung Hai-Fütterung Rochen-Fütterung Sonnenuntergangs-Kreuzfahrt Sonnenaufgangs-Kreuzfahrt Äquator-Ausflug</p><p>Jetski-Fahren Bananenboot-Fahren Kajak-Fahren Windsurfen Parasailing Wasserski Katamaran-Fahrt</p><figure><img src="legacy/images/articles/dolphin-cruise.webp" alt="maldives" loading="lazy" /></figure>', 'Dinge, die man auf den Maldiven tun kann | Maldiven Reiseführer | MTG', 'Die Top 12 Aktivitäten auf den Maldiven für Ihren Urlaub. Die meisten dieser Aktivitäten sind in allen Resorts verfügbar.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'most-famous-places-in-the-world'), 'article', 'de', 'die-beruehmtesten-orte-der-welt', 'Die berühmtesten Orte der Welt', 'Liste der berühmtesten Orte und Reiseziele der Welt mit Fakten für Touristen.', null, '<p>Autor: Shayad Saeed</p><p>Datum: 02.02.2021</p><p>Es gibt Hunderte berühmter Orte auf der Welt, von denen ich die Top 10 der bekanntesten gemäß meinen Recherchen hervorheben werde. Wir gewinnen ein Gefühl für einen Ort durch Sehenswürdigkeiten. Diese historischen Stätten und Naturwunder verbinden uns mit einem Ort und verleiten uns dazu, ihn zu besuchen. Der Eiffelturm befindet sich in Paris, und die Freiheitsstatue befindet sich in New York City. Diese 10 Attraktionen, die alle für ihre jeweiligen Orte und ihre Geschichte von Bedeutung sind, sollten auf Ihrer Reise-Wunschliste stehen.</p><figure><img src="legacy/images/articles/ar/famous-places-in-the-world.webp" alt="famous places in the world" loading="lazy" /></figure><h4>Burj Khalifa, Dubai</h4><p>In Dubai, in den Vereinigten Arabischen Emiraten, ist der Burj Khalifa ein Wolkenkratzer. Er ist seit 2009 das höchste Bauwerk und Gebäude der Welt, mit einer Gesamthöhe von 829,8 m (etwas mehr als eine halbe Meile) (zuvor war es der Taipei 101). Die folgenden Rekorde sind mit dem Burj Khalifa verbunden:</p><p>Diese Rekorde machen ihn zu einem der besten Orte der Welt.</p><figure><img src="legacy/images/articles/ar/famous-places-on-the-world.webp" alt="famous places on the world" loading="lazy" /></figure><h4>Der Eiffelturm, Frankreich</h4><p>Der Eiffelturm, auf Französisch auch La Tour Eiffel genannt, war das Herzstück der Pariser Weltausstellung von 1889. Er wurde errichtet, um das hundertjährige Jubiläum der Französischen Revolution zu feiern und der Welt die industrielle Stärke Frankreichs zu zeigen. Später wurde er aus folgenden Gründen zum Symbol der Stadt:</p><figure><img src="legacy/images/articles/ar/most-famous-places-in-the-world.webp" alt="most famous places in the world" loading="lazy" /></figure><h4>Das Sydney Opera House</h4><p>Das Sydney Opera House ist ein Zentrum für darstellende Künste mit mehreren Veranstaltungsorten in Sydney, New South Wales, Australien, am Sydney Harbour gelegen. Es ist eines der bekanntesten und markantesten Bauwerke des zwanzigsten Jahrhunderts.</p><figure><img src="legacy/images/articles/ar/famous-destinations-in-the-world.webp" alt="famous destinations in the world" loading="lazy" /></figure><h4>Freiheitsstatue: New York</h4><p>Die Freiheitsstatue ist eines der bekanntesten Wahrzeichen der Vereinigten Staaten und steht im New York Harbor. Das Denkmal wurde 1886 vom französischen Volk errichtet, um die Freundschaft zwischen den beiden Ländern zu symbolisieren, und wurde 1924 zum nationalen Denkmal erklärt. Die Statue ist mit der Fähre vom Battery Park in Lower Manhattan aus erreichbar, die sowohl auf Ellis Island als auch auf Liberty Island anlegt.</p><figure><img src="legacy/images/articles/ar/best-places-in-the-world.webp" alt="best places in the world" loading="lazy" /></figure><h4>Die Große Pyramide von Gizeh: Kairo, Ägypten</h4><p>Die Große Pyramide von Gizeh und die umliegenden Pyramiden sind über 4.000 Jahre alt. Sie liegen außerhalb von Kairo, entlang des Nils. Diese etwa 2500 v. Chr. von König Khufu erbauten antiken Ruinen sind auch eines der Sieben Weltwunder der Antike – und das einzige, das noch heute steht.</p><figure><img src="legacy/images/articles/ar/famous-destinations.webp" alt="famous destinations" loading="lazy" /></figure><h4>Marina Bay Sands, Singapur</h4><p>Das Marina Bay Sands ist ein Hotel- und Einkaufsviertel im Stadtteil Downtown Core von Singapur. Es wurde bei seiner Eröffnung 2010 als die teuerste eigenständige Casino-Immobilie der Welt angekündigt und kostete 8 Milliarden Singapur-Dollar (6,88 Milliarden US-Dollar) einschließlich Grundstück.</p><figure><img src="legacy/images/articles/ar/famous-places.webp" alt="famous places" loading="lazy" /></figure><h4>Taj Mahal: Agra, Indien</h4><p>Das Taj Mahal wurde für die Frau des Kaisers Shah Jahan errichtet. Die UNESCO hat das 1648 fertiggestellte Gebäude als bestes Beispiel indo-islamischer Architektur ausgezeichnet. Das Taj Mahal befindet sich in der Stadt Agra und ist von der Hauptstadt Neu-Delhi aus mit einem einstündigen Flug oder einer dreistündigen Zugfahrt zu erreichen. Aufgrund der großen Menschenmengen an dieser Attraktion ist es besser, während der Woche zu kommen. Der Sonnenaufgang taucht das weiße Marmorbauwerk in ein bezauberndes Licht.</p><figure><img src="legacy/images/articles/ar/famous-places-to-visit-in-the-world.webp" alt="famous places to visit in the world" loading="lazy" /></figure><h4>Die Inseln der Malediven</h4><p>Die Malediven sind eine Kette von 1.200 Inseln im Indischen Ozean. Die Malediven sind bekannt für ihre Einzigartigkeit und natürliche Schönheit. Aufgrund ihrer geografischen Lage ist es am besten, sie zwischen Oktober und Mai zu besuchen. Aus folgenden Gründen gelten sie als einer der besten Orte, die man besuchen kann:</p><figure><img src="legacy/images/articles/ar/best-places-to-tavel-in-the-world.webp" alt="best places to tavel in the world" loading="lazy" /></figure><h4>Insel Bora Bora</h4><p>Bora Bora ist eine kleine Insel vor der Küste Polynesiens (nur etwa 10 km lang und knapp über 3 km breit). In ihrem Zentrum erhebt sich ein erloschener Vulkan, der sich in einen üppigen Dschungel öffnet, bevor er in eine türkisfarbene Lagune übergeht. Diese Details machen sie zu einem der besten Reiseziele:</p><figure><img src="legacy/images/articles/ar/famous-places-to-travel-in-the-world.webp" alt="famous places to-travel in the world" loading="lazy" /></figure><h4>Südinsel, Neuseeland</h4><p>Die Südinsel Neuseelands ist an jeder Ecke voller majestätischer Landschaften und ist ein UNESCO-Weltnaturerbe. Die folgenden Fakten machen sie zu einem der berühmten Reiseziele.</p>', 'Die berühmtesten Orte der Welt | Maldiven Reiseführer | MTG', 'Liste der berühmtesten Orte und Reiseziele der Welt mit Fakten für Touristen.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'maldives-honeymoon-ultimate-romantic-getaway-guide'), 'article', 'de', 'maldiven-flitterwochen-ultimativer-romantischer-guide', 'Maldiven-Flitterwochen: Der ultimative Guide für den romantischen Rückzugsort', 'Kompletter Maldiven-Flitterwochen-Guide – Entdecken Sie die besten romantischen Resorts, Overwater-Bungalows, Pakete und einzigartige Erlebnisse für Ihren perfekten Paar-Urlaub im Paradies.', null, '<figure><img src="legacy/images/maldives-honeymoons.webp" alt="Romantic Maldives honeymoon couple on beach" loading="lazy" /></figure><p>Die Malediven gelten unangefochten als das Paradies für Flitterwöchner und bieten Neuvermählten eine exquisite Mischung aus natürlicher Schönheit, Privatsphäre und Romantik. Dieser Archipel aus 1.192 Koralleninseln, verteilt über den Indischen Ozean, hat die Kunst des Paar-Urlaubs perfektioniert, mit Resorts, die speziell dafür konzipiert sind, unvergessliche romantische Erlebnisse zu schaffen.</p><p>Was die Malediven von anderen tropischen Reisezielen unterscheidet, ist ihre einzigartige Geografie – jedes Resort befindet sich typischerweise auf seiner eigenen privaten Insel, was völlige Abgeschiedenheit gewährleistet. Die ikonischen Overwater-Bungalows, die die Malediven als Pioniere eingeführt haben, lassen Paare zum sanften Plätschern der Wellen unter ihrer Villa aufwachen und direkt in kristallklare Lagunen eintauchen.</p><p>Über die reine Schönheit hinaus sind maledivische Resorts darauf spezialisiert, personalisierte romantische Erlebnisse zu schaffen. Von privaten Sandbank-Picknicks bis hin zu Unterwasser-Speisesälen, umgeben von Meereslebewesen – die Möglichkeiten, besondere Momente zu schaffen, sind endlos. Die muslimische Kultur des Landes bedeutet, dass öffentliche Zuneigungsbekundungen den Resort-Inseln vorbehalten sind, was eine diskrete, intime Atmosphäre schafft, die perfekt für Flitterwöchner ist.</p><h2>Warum die Malediven das ultimative Ziel für Flitterwochen sind</h2><figure><img src="legacy/images/activities/virgin-islands-excursion.webp" alt="Private island in Maldives" loading="lazy" /></figure><p>Mehrere Schlüsselfaktoren machen die Malediven zum weltweit führenden Ziel für Flitterwochen:</p><h4>1. Unübertroffene Privatsphäre</h4><p>Im Gegensatz zu überfüllten Strandzielen bieten maledivische Resorts echte Abgeschiedenheit. Die meisten befinden sich auf privaten Inseln mit nur 50–150 Villen, was bedeutet, dass Sie oft ganze Strandabschnitte für sich allein haben. Die Resort-Inseln sind sorgfältig gestaltet, um die Privatsphäre zu maximieren, mit Vegetationspuffern zwischen den Unterkünften.</p><h4>2. Das Overwater-Bungalow-Erlebnis</h4><p>Die Malediven haben das Konzept der luxuriösen Overwater-Villa erfunden. Moderne Varianten verfügen über Glasboden-Paneele, private Infinity-Pools und direkten Lagunenzugang. Lesen Sie unseren vollständigen Leitfaden zu maledivischen Overwater-Bungalows, um Details zur Auswahl des perfekten Bungalows zu erhalten.</p><h4>3. All-inclusive-Romantik</h4><p>Resorts sind darauf spezialisiert, unkomplizierte romantische Erlebnisse zu bieten. Butler können alles organisieren, von überraschenden Heiratsanträgen bis zu Jubiläumsfeiern. Die meisten bieten spezielle Flitterwochen-Pakete mit inkludierten romantischen Extras an.</p><h4>4. Ganzjährig warmes Wetter</h4><p>Mit durchschnittlichen Temperaturen von 28–30 °C und Wassertemperaturen von rund 27 °C das ganze Jahr über sind die Malediven immer bereit für Flitterwochen. Es gibt zwar eine Regenzeit, aber die Schauer sind in der Regel kurz.</p><h4>5. Unvergleichliches Meeresleben</h4><p>Die Korallenatolle der Malediven schaffen perfekte Bedingungen für vielfältiges Meeresleben. Viele Resorts haben ausgezeichnete Hausriffe, an denen Sie direkt von Ihrer Villa aus mit Schildkröten, Rochen und tropischen Fischen schnorcheln können.</p><h2>Die 5 besten Maledivenresorts für Flitterwochen</h2><figure><img src="legacy/resorts/four-seasons-huraa/images/four-seasons-maldives-at-kuda-huraa-sunset-water-bangalow1.webp" alt="Four Seasons Kuda Huraa overwater bungalow" loading="lazy" /></figure><h3>1. Four Seasons Resort Maldives at Kuda Huraa</h3><p>Diese legendäre Unterkunft setzt den Standard für Flitterwochen auf den Malediven und bietet:</p><ul><li>Kürzlich renovierte Overwater-Bungalows mit 24/7-Butler-Service</li><li>Private Infinity-Pools in den Premium-Villen</li><li>Weltberühmtes Spa mit Behandlungsräumen über dem Wasser</li><li>Sieben Restaurants, darunter einen Meeresfrüchte-Grill am Riff</li><li>Kostenlose Walhai-Ausflüge je nach Saison</li></ul><p>Flitterwochen-Paket: Beinhaltet Champagner, Paar-Massage, private Sonnenuntergangs-Kreuzfahrt und romantisches Dinner (Mindestaufenthalt 5 Nächte)</p><p>Am besten geeignet für: Paare, die tadellosen Service und Luxus wünschen</p><figure><img src="legacy/resorts/baros-island/images/baros-maldives-island-resort-beach-dinner.webp" alt="Baros Maldives beach dinner" loading="lazy" /></figure><h3>2. Baros Maldives</h3><p>Dieses intime Boutique-Resort ist perfekt für Paare, die Privatsphäre suchen:</p><ul><li>Nur 75 Villen auf einer kleinen privaten Insel</li><li>Villen eingebettet in üppige Vegetation für maximale Privatsphäre</li><li>Ausgezeichnetes Hausriff, das vom Strand aus zugänglich ist</li><li>Ikonisches Lighthouse Restaurant über der Lagune</li><li>Personalisierte romantische Erlebnisse</li></ul><p>Flitterwochen-Paket: Beinhaltet Champagner, Obstkorb, 60-minütige Spa-Behandlung und privates Dinner (Mindestaufenthalt 4 Nächte)</p><p>Am besten geeignet für: Paare, die Intimität und natürliche Schönheit schätzen</p><h2>Maldiven-Flitterwochen-Pakete erklärt</h2><figure><img src="legacy/images/romantic-sunrise-breakfast.webp" alt="Romantic breakfast in Maldives" loading="lazy" /></figure><p>Fast alle maledivischen Resorts bieten spezielle Flitterwochen-Pakete an. Diese erfordern in der Regel einen Nachweis der Eheschließung innerhalb der letzten 6–12 Monate. Wichtige Bestandteile:</p><h4>Standardleistungen:</h4><ul><li>Willkommens-Champagner und Obstkorb</li><li>Romantische Bettdekoration</li><li>Paar-Massage (meist 30–60 Minuten)</li><li>Spezieller Flitterwochen-Kuchen oder Dessert</li><li>Erinnerungszertifikat oder Geschenk</li></ul><h4>Premium-Zusatzleistungen:</h4><ul><li>Private Sonnenuntergangs-Kreuzfahrt</li><li>Dinner am Strand unter den Sternen</li><li>Garantiertes Villa-Upgrade</li><li>Fotosession mit professionellem Fotografen</li><li>Personalisierte Ausflüge wie private Yacht-Charter</li></ul><h2>Unvergessliche romantische Erlebnisse</h2><figure><img src="legacy/images/articles/ozen-maadhoo-underwater-restaurant.webp" alt="Underwater restaurant Maldives" loading="lazy" /></figure><h4>1. Unterwasser-Dining</h4><p>Mehrere Resorts verfügen über unglaubliche Unterwasserrestaurants, in denen Sie umgeben von Meereslebewesen speisen. Das berühmteste ist Ithaa im Conrad Maldives, das weltweit erste Unterwasserrestaurant, das vollständig aus Glas besteht.</p><figure><img src="legacy/images/stargazing-on-the-maldives-beach.webp" alt="Stargazing in Maldives" loading="lazy" /></figure><h4>2. Privates Sternebeobachten</h4><p>Mit minimaler Lichtverschmutzung bieten die Malediven einen spektakulären Nachthimmel. Einige Resorts stellen Teleskope und Astronomen zur Verfügung, die Sie durch die Sternbilder führen, während Sie auf Ihrer privaten Terrasse entspannen.</p>', 'Maldiven-Flitterwochen: Der ultimative Guide für den romantischen Rückzugsort | Maldiven Reiseführer | MTG', 'Kompletter Maldiven-Flitterwochen-Guide – Entdecken Sie die besten romantischen Resorts, Overwater-Bungalows, Pakete und einzigartige Erlebnisse für Ihren perfekten Paar-Urlaub im Paradies.', 'published', 'claude')
on conflict (entity_id, locale) do update set
  slug = excluded.slug, title = excluded.title, short_description = excluded.short_description,
  body_html = excluded.body_html, meta_title = excluded.meta_title, meta_description = excluded.meta_description,
